"use client"
import React, { useState } from "react"
import useOrderStore from "@/store/orderStore"
import Image from "next/image"
import { Eye, X } from "lucide-react"

function OrdersPage() {
  const { orders, updateOrderStatus } = useOrderStore()
  const [selectedOrder, setSelectedOrder] = useState(null)
  console.log(selectedOrder)
  const closeModal = () => setSelectedOrder(null)

  const handleCancelOrder = (id) => {
    updateOrderStatus(id, "Cancelled")
    closeModal()
  }

  return (
    <div className="max-w-6xl mx-auto p-4">
      {orders && orders.length > 0 ? (
        <div className="overflow-x-auto">
          <table className="w-full border border-gray-200 text-sm">
            <thead className="bg-gray-100">
              <tr>
                <th className="p-3 text-left">Product</th>
                <th className="p-3">Order ID</th>
                <th className="p-3">Date</th>
                <th className="p-3">Status</th>
                <th className="p-3">Amount</th>
                <th className="p-3">Action</th>
              </tr>
            </thead>
            <tbody>
              {orders.map((order) => (
                <tr
                  key={order.id}
                  className="border-t hover:bg-gray-50 transition"
                >
                  <td className="p-3 flex items-center gap-3">
                    <Image
                      src={order.image}
                      alt={order.name}
                      width={50}
                      height={50}
                      className="rounded-md"
                    />
                    <span className="font-medium">{order.name}</span>
                  </td>
                  <td className="px-15 lg:p-3 lg:text-center">{order.id}</td>
                  <td className="p-3 text-center">{order.createdAt}</td>
                  <td className="p-3 text-center">
                    <span
                      className={`px-2 py-1 rounded text-xs ${order.status === "Delivered"
                        ? "bg-green-300 text-black"
                        : order.status === "Cancelled"
                          ? "bg-red-400 text-white"
                          : "bg-yellow-300 text-black"
                        }`}
                    >
                      {order.status}
                    </span>
                  </td>
                  <td className="p-3 text-center">Rs {order.amount.toLocaleString()}</td>
                  <td className="p-3 text-center">
                    <button
                      onClick={() => setSelectedOrder(order)}
                      className="p-2 rounded-full hover:text-red-500 active:text-red-700 cursor-pointer"
                    >
                      <Eye size={18} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : (
        <p>No orders found.</p>
      )}

      {/* ====================== MODAL ====================== */}

      {selectedOrder && (
        <div className="fixed inset-0 bg-black/50 flex justify-center items-center z-50">
          <div className="bg-white rounded-lg w-full max-w-3xl p-6 relative shadow-lg overflow-y-auto max-h-[90vh]">
            {/* Close button */}
            <button
              onClick={closeModal}
              className="absolute top-3 right-3 text-gray-500 hover:text-red-500 active:text-red-700 cursor-pointer"
            >
              <X size={20} />
            </button>

            {/* Header */}
            <h2 className="text-xl font-bold mb-2">Order #{selectedOrder.id}</h2>
            <p className="text-sm text-gray-500 mb-4">
              Placed on {selectedOrder.date}
            </p>

            {/* Order Summary */}
            <div className="grid md:grid-cols-2 gap-6 mb-6 text-sm">
              <div className="space-y-2">
                <h3 className="font-semibold text-gray-700">Order Summary</h3>
                <p><span className="font-medium">Payment Method:</span> {selectedOrder.paymentMethod}</p>
                <p><span className="font-medium">Payment Status:</span> {selectedOrder.paymentStatus}</p>
                <p><span className="font-medium">Total Amount:</span> Rs {selectedOrder.amount}</p>
              </div>
              <div className="space-y-2">
                <h3 className="font-semibold text-gray-700">Shipping Address</h3>
                <p>{selectedOrder.fullName}</p>
                <p>{selectedOrder.city}, {selectedOrder.district}</p>
                <p>{selectedOrder.province}</p>
                <p>{selectedOrder.phoneNumber}</p>
              </div>
            </div>

            {/* Order Items */}
            <h3 className="font-semibold text-gray-700 mb-2">Order Items</h3>
            <div className="border rounded-lg divide-y">
              <div className="grid grid-cols-4 text-xs font-medium text-gray-600 p-2">
                <span>Product</span>
                <span className="text-center">Quantity</span>
                <span className="text-center">Price</span>
                <span className="text-center">Total</span>
              </div>
              <div className="grid grid-cols-4 items-center p-2">
                <div className="flex items-center gap-2">
                  <Image
                    src={selectedOrder.image}
                    alt={selectedOrder.name}
                    width={40}
                    height={40}
                    className="rounded-md"
                  />
                  <span className="text-sm">{selectedOrder.name}</span>
                </div>
                <span className="text-center">{selectedOrder.quantity}</span>
                <span className="text-center">Rs {selectedOrder.amount / selectedOrder.quantity}</span>
                <span className="text-center font-medium">Rs {selectedOrder.amount}</span>
              </div>
            </div>

        
            {/* Delivery Tracking */}
            <div className="mt-6">
              <h3 className="font-semibold text-gray-700 mb-4">Delivery Progress</h3>

              {/* Progress Steps */}
              <div className="flex items-center justify-between relative mb-4">
                {/* Stage 1: Placed */}
                <div className="flex flex-col items-center relative z-10">
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center border-2 transition-all duration-300 ${selectedOrder.status !== 'Cancelled'
                      ? 'bg-green-500 border-green-500 text-white'
                      : 'bg-green-500 border-green-500 text-white'
                    }`}>
                    <Check size={16} />
                  </div>
                  <span className="mt-2 text-xs font-medium text-green-600">Placed</span>
                </div>

                {/* Stage 2: Approved */}
                <div className="flex flex-col items-center relative z-10">
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center border-2 transition-all duration-300 ${['Approved', 'Processing', 'Shipped', 'Delivered'].includes(selectedOrder.status)
                      ? 'bg-green-500 border-green-500 text-white'
                      : 'bg-white border-gray-300 text-gray-400'
                    }`}>
                    {['Approved', 'Processing', 'Shipped', 'Delivered'].includes(selectedOrder.status) ? (
                      <Check size={16} />
                    ) : (
                      <span className="text-sm font-medium">2</span>
                    )}
                  </div>
                  <span className={`mt-2 text-xs font-medium transition-colors duration-300 ${['Approved', 'Processing', 'Shipped', 'Delivered'].includes(selectedOrder.status)
                      ? 'text-green-600'
                      : 'text-gray-500'
                    }`}>
                    Approved
                  </span>
                </div>

                {/* Stage 3: Delivered */}
                <div className="flex flex-col items-center relative z-10">
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center border-2 transition-all duration-300 ${selectedOrder.status === 'Delivered'
                      ? 'bg-green-500 border-green-500 text-white'
                      : 'bg-white border-gray-300 text-gray-400'
                    }`}>
                    {selectedOrder.status === 'Delivered' ? (
                      <Check size={16} />
                    ) : (
                      <span className="text-sm font-medium">3</span>
                    )}
                  </div>
                  <span className={`mt-2 text-xs font-medium transition-colors duration-300 ${selectedOrder.status === 'Delivered' ? 'text-green-600' : 'text-gray-500'
                    }`}>
                    Delivered
                  </span>
                </div>

                {/* Progress Line */}
                <div className="absolute top-5 left-0 w-full h-0.5 bg-gray-300 -z-10">
                  <div
                    className="h-full bg-green-500 transition-all duration-500 ease-in-out"
                    style={{
                      width: selectedOrder.status === 'Pending' || selectedOrder.status === 'Cancelled' ? '0%' :
                        ['Approved', 'Processing', 'Shipped'].includes(selectedOrder.status) ? '50%' :
                          selectedOrder.status === 'Delivered' ? '100%' : '0%'
                    }}
                  />
                </div>
              </div>

              {/* Status Message */}
              <div className="text-center">
                <p className={`text-sm font-medium ${selectedOrder.status === 'Cancelled' ? 'text-red-600' :
                    selectedOrder.status === 'Delivered' ? 'text-green-600' :
                      'text-blue-600'
                  }`}>
                  Current Status: {selectedOrder.status}
                </p>
                {selectedOrder.estimatedDelivery && selectedOrder.status !== 'Delivered' && selectedOrder.status !== 'Cancelled' && (
                  <p className="text-xs text-gray-500 mt-1">
                    Estimated Delivery: {selectedOrder.estimatedDelivery}
                  </p>
                )}
              </div>
            </div>


          </div>
        </div>
      )}

    </div>
  )
}

export default OrdersPage
